import { createEditor, Language } from './editor';
import { transpile } from './transpiler';
import { Preview } from './preview';
import { getStyles } from './styles';
import { getTheme, defaultTheme } from './themes';

class CodePlaygroundReact extends HTMLElement {
  private shadow: ShadowRoot;
  private editorController: ReturnType<typeof createEditor> | null = null;
  private preview: Preview | null = null;
  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
  private _code = '';
  private _lang: Language = 'tsx';
  private _allowForms = true;
  private _langBadge: HTMLSpanElement | null = null;
  private styleTag: HTMLStyleElement | null = null;
  private playgroundEl: HTMLElement | null = null;
  private _height: string | null = null;
  private initialized = false;

  constructor() {
    super();
    this.shadow = this.attachShadow({ mode: 'open' });
  }

  connectedCallback(): void {
    this.render();
  }

  disconnectedCallback(): void {
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
    }
    this.preview?.destroy();
    this.editorController?.view.destroy();
  }

  static get observedAttributes(): string[] {
    return ['code', 'theme', 'lang', 'height', 'allow-forms'];
  }

  get allowForms(): boolean {
    return this._allowForms;
  }

  set allowForms(value: boolean) {
    this.setAttribute('allow-forms', value ? 'true' : 'false');
  }

  private parseLang(value: string | null): Language {
    const langs: Record<string, Language> = { jsx: 'jsx', tsx: 'tsx' };
    return langs[value ?? ''] || 'tsx';
  }

  private parseAllowForms(value: string | null): boolean {
    if (value === null) return true;
    return value !== 'false' && value !== '0';
  }

  private parseHeight(value: string | null): string | null {
    const v = (value ?? '').trim();
    if (!v) return null;
    if (/^\d+(\.\d+)?$/.test(v)) return `${v}px`;
    if (/^\d+(\.\d+)?(px|rem|em|vh|vw|vmin|vmax|%)$/.test(v)) return v;
    return null;
  }

  private applyHeight(): void {
    if (!this.playgroundEl) return;
    if (this._height) {
      this.playgroundEl.style.height = this._height;
      this.playgroundEl.style.minHeight = '0';
    } else {
      this.playgroundEl.style.height = '';
      this.playgroundEl.style.minHeight = '';
    }
  }

  attributeChangedCallback(name: string, _old: string | null, value: string | null): void {
    if (name === 'code' && value !== null && value !== this._code) {
      this._code = value;
      if (this.editorController) {
        this.editorController.view.dispatch({
          changes: { from: 0, to: this.editorController.view.state.doc.length, insert: value },
        });
      }
    }
    if (name === 'theme' && value !== null && this.initialized) {
      const theme = getTheme(value);
      this.editorController?.updateTheme(theme);
      if (this.styleTag) {
        this.styleTag.textContent = getStyles(theme);
      }
    }
    if (name === 'lang' && value !== null && this.initialized) {
      this._lang = this.parseLang(value);
      this.editorController?.updateLang(this._lang);
      this.updateLangBadge();
    }
    if (name === 'height') {
      this._height = this.parseHeight(value);
      this.applyHeight();
    }
    if (name === 'allow-forms') {
      this._allowForms = this.parseAllowForms(value);
      this.preview?.setAllowForms(this._allowForms);
    }
  }

  private getInitialCode(): string {
    const attrCode = this.getAttribute('code');
    if (attrCode !== null) return this.dedent(attrCode);
    const script = this.querySelector('script[type="text/plain"]');
    if (script) return this.dedent(script.textContent || '');
    const template = this.querySelector('template');
    if (template) return this.dedent(template.innerHTML);
    const text = this.textContent;
    if (text?.trim()) return this.dedent(text);

    const lang = this.parseLang(this.getAttribute('lang'));
    if (lang === 'jsx') {
      return `import { useState } from 'react';

function App() {
  const [count, setCount] = useState(0);
  return (
    <div style={{ textAlign: 'center', padding: '20px' }}>
      <h1>JSX Counter</h1>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>+</button>
    </div>
  );
}

export default App;`;
    }

    return `import { useState } from 'react';

interface Props {
  initial?: number;
}

function App({ initial = 0 }: Props) {
  const [count, setCount] = useState<number>(initial);
  return (
    <div style={{ textAlign: 'center', padding: '20px' }}>
      <h1>TSX Counter</h1>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>+</button>
    </div>
  );
}

export default App;`;
  }

  private dedent(code: string): string {
    const lines = code.split('\n');
    if (lines.length === 0) return '';
    const minIndent = lines
      .filter(l => l.trim())
      .reduce((min, l) => Math.min(min, l.search(/\S/)), Infinity);
    if (minIndent === Infinity || minIndent === 0) return code.trim();
    return lines.map(l => l.slice(minIndent)).join('\n').trim();
  }

  private render(): void {
    const theme = getTheme(this.getAttribute('theme') ?? undefined);

    this.styleTag = document.createElement('style');
    this.styleTag.textContent = getStyles(theme);
    this.shadow.appendChild(this.styleTag);

    const wrapper = document.createElement('div');
    wrapper.className = 'playground';
    this.playgroundEl = wrapper;
    this.shadow.appendChild(wrapper);

    this._height = this.parseHeight(this.getAttribute('height'));
    this.applyHeight();

    const editorContainer = document.createElement('div');
    editorContainer.className = 'editor-panel';
    wrapper.appendChild(editorContainer);

    const editorToolbar = document.createElement('div');
    editorToolbar.className = 'toolbar';
    editorToolbar.innerHTML = '<span class="toolbar-label">Editor</span>';
    this._langBadge = document.createElement('span');
    this._langBadge.className = 'lang-badge';
    editorToolbar.appendChild(this._langBadge);
    editorContainer.appendChild(editorToolbar);

    const editorBody = document.createElement('div');
    editorBody.style.height = 'calc(100% - 32px)';
    editorContainer.appendChild(editorBody);

    const previewContainer = document.createElement('div');
    previewContainer.className = 'preview-panel';
    wrapper.appendChild(previewContainer);

    const previewToolbar = document.createElement('div');
    previewToolbar.className = 'preview-header';
    previewToolbar.innerHTML = '<span class="toolbar-label">Preview</span>';
    previewContainer.appendChild(previewToolbar);

    const previewBody = document.createElement('div');
    previewBody.style.height = 'calc(100% - 28px)';
    previewContainer.appendChild(previewBody);

    requestAnimationFrame(() => {
      const code = this.getInitialCode();
      this._code = code;

      this._allowForms = this.parseAllowForms(this.getAttribute('allow-forms'));
      this.preview = new Preview(previewBody, { allowForms: this._allowForms });

      const lang = this.parseLang(this.getAttribute('lang'));
      this._lang = lang;
      this.updateLangBadge();

      this.editorController = createEditor(editorBody, code, (newCode: string) => {
        this._code = newCode;
        this.debouncedExecute(newCode);
      }, theme, lang);

      this.preview.waitReady().then(() => {
        this.executeCode(code);
      });

      this.initialized = true;
    });
  }

  private debouncedExecute(code: string): void {
    if (this.debounceTimer) clearTimeout(this.debounceTimer);
    this.debounceTimer = setTimeout(() => {
      this.executeCode(code);
    }, 400);
  }

  private updateLangBadge(): void {
    if (this._langBadge) {
      this._langBadge.textContent = this._lang;
    }
  }

  private executeCode(raw: string): void {
    if (!this.preview) return;
    try {
      const transpiled = transpile(raw, this._lang);
      this.preview.execute(transpiled);
    } catch (err: unknown) {
      this.preview.showError(err instanceof Error ? err.message : String(err));
    }
  }
}

customElements.define('code-playground-react', CodePlaygroundReact);

export default CodePlaygroundReact;
